import{_ as t,o as s,c as u,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const b=JSON.parse('{"title":"Häufige Fehler vor dem Zeugnisdruck vermeiden","description":"","frontmatter":{"title":"Häufige Fehler vor dem Zeugnisdruck vermeiden","source_pageid":1426,"source_revision":7108},"headers":[],"relativePath":"zeugnisse/vorbereitung/beliebte-fehler-beim-zeugnisdruck-tutorial.md","filePath":"zeugnisse/vorbereitung/beliebte-fehler-beim-zeugnisdruck-tutorial.md"}'),l={name:"zeugnisse/vorbereitung/beliebte-fehler-beim-zeugnisdruck-tutorial.md"};function a(d,i,g,o,h,c){return s(),u("div",null,[...i[0]||(i[0]=[r('<h1 id="haufige-fehler-vor-dem-zeugnisdruck-vermeiden" tabindex="-1">Häufige Fehler vor dem Zeugnisdruck vermeiden <a class="header-anchor" href="#haufige-fehler-vor-dem-zeugnisdruck-vermeiden" aria-label="Permalink to &quot;Häufige Fehler vor dem Zeugnisdruck vermeiden&quot;">​</a></h1><p>Kontrollieren Sie Datenaufbereitung, Reportkonfiguration und Druckeinstellungen. Die Sammlung hilft, typische Fehler vor der endgültigen Ausgabe zu erkennen.</p><h2 id="datenaufbereitung" tabindex="-1">Datenaufbereitung <a class="header-anchor" href="#datenaufbereitung" aria-label="Permalink to &quot;Datenaufbereitung&quot;">​</a></h2><ul><li><p><strong>Daten</strong></p><ul><li><strong>Fehlendes Versetzungs- und/oder Zeugnisdatum</strong> (bei allen Daten verwendet SchILD-NRW <em>1899</em> als Standarddatum, um auf einen Fehler hinzuweisen).</li><li><strong>Kein Abgangs- oder Abschlussdatum</strong> bei Abgangs- oder Abschlusszeugnissen gesetzt, so dass SchILD-NRW trotz korrektem Zeugnisdatum ein falsches Datum druckt.</li><li>Fehlerhafte Einstellung eines Datums (z.B. &quot;Zeugnisdatum&quot; statt &quot;Abmeldedatum&quot; beim Abgangszeugnis bei einem Schüler, der eigentlich in der EF versetzt wird, sich dann aber doch abmeldet und noch ein Abgangszeugnis ausgestellt bekommt).</li></ul></li><li><p>Die <strong>Fehlstunden</strong> wurden noch nicht erfasst.</p></li><li><p>Die <strong>Fehlstunden</strong> wurden zwar <strong>kursweise</strong> eingetragen, aber es wurde der Gruppenprozess zur Berechnung der Fehlstundensummen nicht ausgeführt. Gleiches gilt nach der Änderung von fachbezogenen Fehlstunden.</p></li><li><p>In der Zeugniskonferenz wurden Notenänderungen vorgenommen, es fand aber keine neue Berechnung von Versetzung und/oder Abschluss statt.</p></li><li><p>Gleiches gilt für die Berechnung eines FHR-Schnitts usw.</p></li><li><p>Bei einem ESA müssen <strong>Lernbereichsnoten</strong> eingegeben werden, die aufgrund einer besseren Prognose zuvor nicht eingetragen wurden.</p></li><li><p>Fehlende <strong>Sprachenfolge</strong>/fehlendes <strong>Sprachniveau</strong>/Handeintragungen (z.B. Latinum) bei Abgangs- oder Abschlusszeugnissen.</p></li><li><p><strong>Lernabschnitte</strong> und deren Wertung</p><ul><li>Lernabschnitte die gewertet sein sollten, sind <em>nicht als gewertet</em> angehakt.</li><li>Alternativ sind <strong>Lernabschnitte</strong>, die nicht gewertet sein sollen als <em>gewertet</em> markiert. Das passiert mitunter bei Wiederholern, wo der vorherige Durchgang noch immer gewertet ist. Dies führt zu fehlerhaften Berechnungen und Leistungsübersichten.</li><li>Mitunter sind damit zwei Lernabschnitte des gleichen Jahrgangs, zum Beispiel die Q1, als <em>gewertet</em> markiert.</li><li>Wiederholte Lernabschnitte sind nicht als <em>2. Durchgang</em> markiert.</li></ul></li></ul><h2 id="druckvorbereitung" tabindex="-1">Druckvorbereitung <a class="header-anchor" href="#druckvorbereitung" aria-label="Permalink to &quot;Druckvorbereitung&quot;">​</a></h2><ul><li>Soll das Gemeinde- oder Stadtwappen mit auf das Zeugnis, muss es von Hand in die Formulare eingefügt werden</li><li>Keine Anpassung der Zeugniseinstellungen.ini für ein &quot;selten&quot; gedrucktes Zeugnis</li><li>Falsche Zeugniseinstellungen.ini-Einstellungen für die jeweils gewünschte Zeugnisanlage (es müssen alle Anlagen zu verwendenden eingestellt werden) - ein Fehler hier könnte sein, wer (Klassenleitung, Abteilungsleitung, Schulleitung, Beratungslehrer, ...) aber auch Namensnennung von 1. und/oder 2. Klassenlehrer mit welchen (Vor-)Namen/Amtsbezeichnungen etc. unterschreiben soll.</li><li>Ein mit SchILD3 erstellter Report beziehungsweise ein Report aus SchILD2, der in SchILD3 geöffnet und neu gespeichert wurde, ist nicht mehr zu SchILD2 kompatibel. Dies gilt auch für zugeschickte oder heruntergeladene Reports.</li></ul>',6),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Wenn Sie einen Report aus SchILD-NRW 2 weiterverwenden, kann ein erneutes Speichern im Reportdesigner von SchILD-NRW 3 nötig sein. Öffnen Sie den Report dort und speichern Sie ihn ohne weitere Änderungen. Dadurch werden die gespeicherten technischen Angaben an die neuere Version des Reportdesigners angepasst."),e("p",null,"Dies betrifft zum Beispiel die interne Verarbeitung von manchen Grafiken für Logos."),e("p",null,"Beachten Sie, dass der Report im Anschluss nicht mehr zu SchILD-NRW2 kompatibel ist.")],-1),r('<h2 id="druck" tabindex="-1">Druck <a class="header-anchor" href="#druck" aria-label="Permalink to &quot;Druck&quot;">​</a></h2><ul><li>Falsches Wenden beim Druck bei mehrseitigen Zeugnissen: <ul><li>A4-Zeugnisse werden über die <em>lange</em> Seite des Blatts gewendet</li><li>A3-Zeugnisse über die <em>kurze</em> Seite des Blatts</li></ul></li><li>Farbdruck erzeugt, wenn das Zeugnis S/W sein soll oder umgekehrt</li><li>wenn bei Abgängern von vor dem letzten Abschnittswechseln ein Halbjahr zu viel steht (ging 2023/24 1. Halbjahr, auf dem Zeugnis steht aber &quot;bis 2023/24, 2. Halbjahr an der Schule&quot;, wurde in der Reportverwaltung aus dem aktuellen Abschnitt und nicht aus dem letzten heraus gedruckt</li><li>Kein dickes Zeugnispapier verwendet (z.B. kein Papierfach im Drucker angegeben und das dicke Papier liegt nicht im Standardfach) <ul><li>Variante: Jemand anderes druckt &quot;normale&quot; Erzeugnisse im Hunderterpack auf das im Drucker bereitliegende/vergessene Zeugnispapier</li></ul></li><li>Es wird keine vorgesehene Archivierung vorgenommen. Dies ist besonders bei Abgangs- oder Abschlusszeugnissen relevant; klären Sie bitte, welches Vorgehen in Ihrer Schule entsprechend des gültigen Rechtsrahmens vorgesehen ist <ul><li>Es wird auf Papier gedruckt, aber es wird keine Ausgabe in die Dokumenten- oder die Zeugnisablage angestoßen</li><li>Es wird keine eigentlich vorgesehene Zeugniskopie (Papier) zur Archivierung in Ordnern durch die Abteilungsleitung angefertigt</li></ul></li></ul>',2),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Drucken Sie die Zeugnisse erst auf Normalpapier und kontrollieren Sie, ob alles korrekt ist. Finden Sie einen Fehler, drucken Sie das korrigierte Zeugnis nach und kontrollieren Sie erneut. Wenn alle Zeugnisse in Ordnung sind, folgt anschließend der Druck auf Zeugnispapier. Der erste Satz auf Normalpapier kann nun direkt zur Archivierung dienen und wird nicht vergessen.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Beliebte_Fehler_beim_Zeugnisdruck_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 7108.")],-1)])])}const p=t(l,[["render",a]]);export{b as __pageData,p as default};
